const request = $('Newsletter Input').first().json;
const row = $input.first()?.json || {};
const deliveryMode = String(request.delivery_mode || '').trim().toLowerCase();
const requestedUserId = String(request.user_id || '').trim();

let userTopics = [];
try {
  const parsed = JSON.parse(row.topics_json || '[]');
  if (Array.isArray(parsed)) {
    userTopics = [...new Set(parsed.map((topic) => String(topic).trim().toLowerCase()).filter(Boolean))];
  }
} catch {}

const storedQuota = Number(row.articles_per_topic);
const articlesPerTopic = Number.isInteger(storedQuota) && storedQuota >= 1 && storedQuota <= 10 ? storedQuota : 3;
const email = String(row.email || '').trim();
const hasValidEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const validMode = deliveryMode === 'manual' || deliveryMode === 'scheduled';
const sameUser = Boolean(row.user_id) && String(row.user_id) === requestedUserId;
const hasConsent = Boolean(String(row.consent_at || '').trim());
const scheduledAllowed = deliveryMode !== 'scheduled' || String(row.newsletter_status || '').toLowerCase() === 'active';
const eligible = validMode && sameUser && hasValidEmail && hasConsent && userTopics.length > 0 && scheduledAllowed;

return [{
  json: {
    user_id: requestedUserId,
    delivery_mode: deliveryMode,
    username_display: String(row.username_display || 'Persona user'),
    email,
    timezone: String(row.timezone || 'Europe/Paris'),
    user_topics: userTopics,
    articles_per_topic: articlesPerTopic,
    newsletter_status: String(row.newsletter_status || ''),
    consent_at: String(row.consent_at || ''),
    last_newsletter_sent_at: String(row.last_newsletter_sent_at || ''),
    eligible,
    status: eligible ? 'eligible' : 'ineligible',
    article_count: 0,
    requested_count: userTopics.length * articlesPerTopic,
    message: eligible ? 'User is eligible for delivery.' : 'Newsletter delivery is not available for this account.'
  }
}];

const user = $('Validate Newsletter User').first().json;
const now = Date.now();
const freshAfter = now - 48 * 60 * 60 * 1000;
const sevenDaysAfter = now - 7 * 24 * 60 * 60 * 1000;
const futureLimit = now + 5 * 60 * 1000;
const userTopics = Array.isArray(user.user_topics) ? user.user_topics : [];
const quotaValue = Number(user.articles_per_topic);
const quota = Number.isInteger(quotaValue) && quotaValue >= 1 && quotaValue <= 10 ? quotaValue : 3;

const escapeHtml = (value) => String(value ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;')
  .replaceAll("'", '&#39;');
const topicLabel = (topic) => topic.charAt(0).toUpperCase() + topic.slice(1);

const candidates = [];
for (const item of $input.all()) {
  const article = item.json || {};
  const published = Date.parse(article.published_at || '');
  if (!Number.isFinite(published) || published < sevenDaysAfter || published > futureLimit) continue;
  if (!String(article.summary || '').trim()) continue;

  let articleTopics = [];
  try {
    const parsed = JSON.parse(article.topics_json || '[]');
    if (Array.isArray(parsed)) articleTopics = parsed.map((topic) => String(topic).trim().toLowerCase()).filter(Boolean);
  } catch {
    continue;
  }
  const primaryTopic = userTopics.find((topic) => articleTopics.includes(topic));
  if (!primaryTopic) continue;

  const url = String(article.url || '').trim();
  const safeUrl = /^https?:\/\/[^\s<>"']+$/i.test(url);
  if (!safeUrl) continue;

  candidates.push({
    id: article.id,
    title: String(article.title || 'Untitled'),
    summary: String(article.summary || ''),
    source: String(article.source || 'Unknown source'),
    url,
    published_at: new Date(published).toISOString(),
    published,
    primary_topic: primaryTopic
  });
}

candidates.sort((a, b) => b.published - a.published || String(a.url).localeCompare(String(b.url)));
const usedIds = new Set();
const usedUrls = new Set();
const groups = [];
const shortages = {};

for (const topic of userTopics) {
  const selected = [];
  const tiers = [
    candidates.filter((article) => article.primary_topic === topic && article.published >= freshAfter),
    candidates.filter((article) => article.primary_topic === topic && article.published < freshAfter),
  ];
  for (const tier of tiers) {
    for (const article of tier) {
      const idKey = article.id == null ? '' : String(article.id);
      if ((idKey && usedIds.has(idKey)) || usedUrls.has(article.url)) continue;
      selected.push(article);
      if (idKey) usedIds.add(idKey);
      usedUrls.add(article.url);
      if (selected.length >= quota) break;
    }
    if (selected.length >= quota) break;
  }
  groups.push({ topic, requested: quota, articles: selected });
  if (selected.length < quota) shortages[topic] = quota - selected.length;
}

const articleCount = groups.reduce((total, group) => total + group.articles.length, 0);
const requestedCount = userTopics.length * quota;
if (articleCount === 0) {
  return [{ json: {
    status: 'no_articles',
    user_id: user.user_id,
    delivery_mode: user.delivery_mode,
    groups,
    shortages,
    article_count: 0,
    requested_count: requestedCount,
    message: 'No matching articles from the last seven days are available yet.'
  } }];
}

let localDate;
try {
  localDate = new Intl.DateTimeFormat('en-CA', { timeZone: user.timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
} catch {
  localDate = new Date().toISOString().slice(0, 10);
}

const sections = groups.map((group) => {
  const cards = group.articles.map((article) =>
    '<article style="border:1px solid #e5e7eb;border-radius:12px;padding:18px;margin:0 0 16px;background:#ffffff">' +
      '<h3 style="font-size:20px;margin:0 0 8px">' + escapeHtml(article.title) + '</h3>' +
      '<p style="color:#4b5563;line-height:1.5">' + escapeHtml(article.summary) + '</p>' +
      '<p style="font-size:13px;color:#6b7280">' + escapeHtml(article.source) + '</p>' +
      '<a href="' + escapeHtml(article.url) + '" style="color:#2563eb">Read the full story</a>' +
    '</article>').join('');
  const shortage = group.articles.length < group.requested
    ? '<p style="font-size:13px;color:#92400e">Only ' + group.articles.length + ' of ' + group.requested + ' recent articles are currently available for this topic.</p>'
    : '';
  return '<section><h2 style="margin-top:28px">' + escapeHtml(topicLabel(group.topic)) + ' — ' + group.articles.length + ' of ' + group.requested + '</h2>' + shortage + cards + '</section>';
}).join('');

const html = '<!doctype html><html><body style="margin:0;background:#f3f4f6;font-family:Arial,sans-serif;color:#111827"><main style="max-width:680px;margin:auto;padding:24px"><h1>Persona</h1><p>Hello ' + escapeHtml(user.username_display) + ', here is your personalized news selection.</p>' + sections + '<p style="font-size:12px;color:#6b7280">To stop scheduled newsletters, use the unsubscribe command in Persona chat.</p></main></body></html>';

return [{ json: {
  status: 'ready',
  user_id: user.user_id,
  delivery_mode: user.delivery_mode,
  recipient: user.email,
  subject: 'Persona — your news for ' + localDate,
  html,
  groups,
  shortages,
  article_count: articleCount,
  requested_count: requestedCount,
  selected_article_ids: groups.flatMap((group) => group.articles.map((article) => article.id)),
  message: 'Newsletter is ready to send.'
} }];

const current = $input.first()?.json || {};
const totalShortage = Object.values(current.shortages || {}).reduce((sum, value) => sum + Math.max(0, Number(value) || 0), 0);
const maxItems = Math.min(20, Math.max(1, Math.ceil(totalShortage * 2)));
return [{ json: { ...current, mode: 'topup', max_items: maxItems, topup_attempted: true } }];

